import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Remove near-duplicates based on correlation
    corr_threshold = 0.6
    correlated_pairs = set()

    # Build correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)

    # Identify near-duplicates and keep only one from each pair
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= corr_threshold:
                correlated_pairs.add((feats.ids[i], feats.ids[j]))

    # Select features to use
    selected_ids = list(feats.ids)
    seen = set()
    for fid in selected_ids:
        # Check if this feature is part of any correlated pair
        is_duplicate = False
        for pair in correlated_pairs:
            if fid in pair:
                # Keep only the first feature in the pair
                if pair[0] == fid and pair[1] in seen:
                    is_duplicate = True
                elif pair[1] == fid and pair[0] in seen:
                    is_duplicate = True
        if not is_duplicate:
            seen.add(fid)

    selected_ids = [fid for fid in selected_ids if fid in seen]

    # If we have no mechanism (very rare case)
    if len(selected_ids) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Filter data to selected features
    selected_indices = [feats.column(fid) for fid in selected_ids]
    x_selected = feats.x[:, selected_indices]

    # Calculate effect sizes using t-test (as proxy for causality)
    effect_sizes = []
    for i, fid in enumerate(selected_ids):
        group0 = x_selected[feats.y == 0, i]
        group1 = x_selected[feats.y == 1, i]
        if len(group0) > 0 and len(group1) > 0:
            t_stat, _ = stats.ttest_ind(group0, group1, equal_var=False)
            effect_sizes.append((abs(t_stat), fid))
        else:
            effect_sizes.append((0, fid))

    # Sort by effect size
    effect_sizes.sort(reverse=True)

    # Select top features for drivers (at most MAX_DRIVERS)
    drivers = tuple([fid for _, fid in effect_sizes[:MAX_DRIVERS]])

    # For logistic regression, we need all features that might be relevant
    columns = tuple(selected_ids)

    # Create products of top features
    products = []
    for i in range(min(3, len(selected_ids))):
        for j in range(i+1, min(4, len(selected_ids))):
            products.append((selected_ids[i], selected_ids[j]))

    # Simple weighted score: sum of top features
    loadings = {}
    for i, fid in enumerate(selected_ids[:5]):
        # Weight by effect size
        loadings[fid] = effect_sizes[i][0] / max(1e-6, effect_sizes[0][0])

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)
